      display: flex;
      flex-direction: column;
    }

    .form-field {
      margin-bottom: 2rem;
      display: flex;
      flex-direction: column;
    }

    .checkbox-wrapper {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    /* Make the checkbox hit target comfortably large (at least 44x44px total bounds roughly) */
    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0.15rem 0 0 0;
      accent-color: #bb86fc;
      cursor: pointer;
    }

    label {
      line-height: 1.5;
      font-size: 1rem;
      cursor: pointer;
    }

    label a {
      color: #bb86fc;
      text-decoration: underline;
      text-underline-offset: 3px;
    }

    label a:hover {
      text-decoration: none;
    }

    .help-text {
      font-size: 0.875rem;
      color: #a0a0a0;
      margin: 0.5rem 0 0 2rem;
    }

    .error-text {
      font-size: 0.875rem;
      color: #cf6679;
      margin: 0.5rem 0 0 2rem;
      font-weight: 500;
    }

    /* Provide highly visible focus states for keyboard users */
    input[type="checkbox"]:focus-visible, 
    button:focus-visible, 
    a:focus-visible {
      outline: 2px solid #bb86fc;
      outline-offset: 2px;
      border-radius: 2px;
    }

    button {
      background-color: #bb86fc;
      color: #121212;
      border: none;
      padding: 0.875rem 1rem;
      font-size: 1rem;
      font-weight: 600;
      border-radius: 4px;
      cursor: pointer;
      width: 100%;
      transition: background-color 0.2s;
    }

    button:hover {
      background-color: #9965f4;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script type="text/babel">
    const TermsForm = () => {
      const [errorMsg, setErrorMsg] = React.useState('');
      const checkboxRef = React.useRef(null);

      const handleSubmit = (e) => {
        e.preventDefault();
        if (!checkboxRef.current.checked) {
          setErrorMsg('Error: You must agree to the terms of use to continue.');
          checkboxRef.current.focus();
        } else {
          setErrorMsg('');
          alert('Registration complete!');
        }
      };

      const handleChange = () => {
        if (checkboxRef.current.checked && errorMsg) {
          setErrorMsg('');
        }
      };

      return (
        <form onSubmit={handleSubmit} noValidate className="consent-form">
          <div className="form-field">
            <div className="checkbox-wrapper">
              <input 
                type="checkbox" 
                id="terms" 
                required 
                ref={checkboxRef}
                onChange={handleChange}
                aria-describedby="terms-help terms-error"
                aria-invalid={errorMsg ? "true" : "false"}
              />
              <label htmlFor="terms">
                I agree to the <a href="#terms">terms of use</a> <span aria-hidden="true">*</span>
                <span className="visually-hidden"> (required)</span>
              </label>
            </div>
            <p id="terms-help" className="help-text">
              Please review the terms of use carefully before proceeding.
            </p>
            <p id="terms-error" className="error-text" hidden={!errorMsg}>
              {errorMsg}
            </p>
          </div>
          <button type="submit">Accept and continue</button>
        </form>
      );
    };

    const App = () => {
      return (
        <main>
          <h1>Create an account</h1>
          <TermsForm />
        </main>
      );
    };

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
